SELECT p.id AS pid, w.id, w.symbol, w.side, w.status, w.quantity, w.price_usdt, w.decision_price_usdt, w.execution_price_observed_at, TIMESTAMPDIFF(MICROSECOND, w.execution_price_observed_at, w.executed_at)/1000 AS obs_age_ms, w.gross_amount_usdt, w.fee_usdt, w.net_amount_usdt, w.cost_basis_usdt, w.realized_pnl_usdt, w.realized_pnl_percent, w.execution_type, w.signal_id, w.execution_key, w.executed_at, LEFT(w.execution_reason, 800) AS execution_reason FROM crypto_ai.paper_position p JOIN crypto_ai.wallet_trade w ON w.symbol = p.symbol AND w.executed_at BETWEEN p.opened_at - INTERVAL 2 MINUTE AND p.closed_at + INTERVAL 2 MINUTE WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, w.executed_at LIMIT 200;